css:
:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}[hidden]{display:none!important}img{max-width:100%}


:root{
  --paper:#F5F7FC; --card:#FFFFFF; --ink:#1B2440; --muted:#5B6484; --faint:#8A92AE;
  --rule:#DCE3F2; --rule-strong:#C9D2EA; --margin:#E0575B;
  --pen:#B5481F; --pen-ink:#FFFFFF; --pen-soft:#FBE9E1;
  --good:#1D8052; --good-soft:#E1F3EA; --bad:#BF3B3B; --bad-soft:#FBE7E6; --warn:#9A6414; --warn-soft:#FBF0DC;
  --masc:#2F6FB5; --masc-soft:#E3EEFA; --fem:#B8406E; --fem-soft:#FAE6EE;
  --shadow:0 1px 2px rgba(27,36,64,.06),0 6px 20px rgba(27,36,64,.07);
  --f-ui:"Atkinson Hyperlegible",system-ui,-apple-system,"Segoe UI",sans-serif;
  --f-word:"Young Serif",Georgia,"Times New Roman",serif;
  --f-hand:"Caveat","Segoe Script","Bradley Hand",cursive;
  --radius:14px;
}
@media (prefers-color-scheme: dark){
  :root:not([data-theme="light"]){
    --paper:#0F1320; --card:#171C2C; --ink:#E7EAF6; --muted:#A1A9C6; --faint:#6F7896;
    --rule:#1C2335; --rule-strong:#283149; --margin:#8C3439;
    --pen:#F2A07E; --pen-ink:#0F1320; --pen-soft:#3A2218;
    --good:#52C992; --good-soft:#15352A; --bad:#F08080; --bad-soft:#3B1D22; --warn:#E6B45E; --warn-soft:#3A2D14;
    --masc:#86B6F0; --masc-soft:#1B2A40; --fem:#F08DB4; --fem-soft:#3A1D2B;
    --shadow:0 1px 2px rgba(0,0,0,.3),0 6px 20px rgba(0,0,0,.25);
  }
}
:root[data-theme="dark"]{
    --paper:#0F1320; --card:#171C2C; --ink:#E7EAF6; --muted:#A1A9C6; --faint:#6F7896;
    --rule:#1C2335; --rule-strong:#283149; --margin:#8C3439;
    --pen:#F2A07E; --pen-ink:#0F1320; --pen-soft:#3A2218;
    --good:#52C992; --good-soft:#15352A; --bad:#F08080; --bad-soft:#3B1D22; --warn:#E6B45E; --warn-soft:#3A2D14;
    --masc:#86B6F0; --masc-soft:#1B2A40; --fem:#F08DB4; --fem-soft:#3A1D2B;
    --shadow:0 1px 2px rgba(0,0,0,.3),0 6px 20px rgba(0,0,0,.25);
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0; background-color:var(--paper); color:var(--ink); font:16px/1.5 var(--f-ui);
  background-image:repeating-linear-gradient(to bottom,transparent 0 31px,var(--rule) 31px 32px);
  -webkit-font-smoothing:antialiased;
}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer}
:focus-visible{outline:3px solid var(--pen);outline-offset:2px;border-radius:8px}
.page{
  position:relative; max-width:600px; margin:0 auto; min-height:100%;
  padding-inline:16px 16px; padding-block:12px calc(96px + env(safe-area-inset-bottom,0px));
}
@media (min-width:640px){
  .page{padding-inline:44px 24px}
  .page::before{content:"";position:absolute;left:28px;top:0;bottom:0;width:2px;background:var(--margin);opacity:.55}
}
/* top bar */
.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:6;display:flex;align-items:flex-end;justify-content:space-between;gap:12px;
  padding-block:10px 12px;margin-inline:-16px;padding-inline:16px;background:color-mix(in srgb,var(--paper) 88%,transparent);backdrop-filter:blur(8px);border-bottom:1px solid var(--rule)}
.titles{display:flex;flex-direction:column;gap:0}
.screen{font-family:var(--f-label,var(--f-ui));font-size:.72rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:700}
.logo{font-family:var(--f-hand);font-size:1.3rem;line-height:1.2;color:var(--pen);margin:0;font-weight:400}
.pill{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:999px;background:var(--card);border:1px solid var(--rule-strong);font-size:.82rem;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}
.pill b{color:var(--ink)}
h2{font-size:1.2rem;margin:0;text-wrap:balance}
h3{font-size:.72rem;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);margin:16px 0 6px;font-weight:700}
p{margin:0}
.muted{color:var(--muted)}
.small{font-size:.86rem}
.stack{display:flex;flex-direction:column;gap:12px}
.card .stack{gap:10px}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.spread{justify-content:space-between}
.card{background:var(--card);border:1px solid var(--rule-strong);border-radius:var(--radius);padding:16px}
.card.lift{box-shadow:var(--shadow);border-color:transparent}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:10px 18px;border-radius:12px;border:1px solid var(--rule-strong);background:var(--card);font-weight:700;text-decoration:none;transition:transform .08s ease,background .15s}
.btn:active{transform:scale(.98)}
.btn.primary{background:var(--pen);border-color:var(--pen);color:var(--pen-ink)}
.btn.ghost{background:transparent;border-color:transparent;color:var(--pen)}
.btn.danger{color:var(--bad);border-color:var(--bad)}
.btn.wide{width:100%}
.btn[disabled]{opacity:.45;cursor:not-allowed}
.icon-btn{width:46px;height:46px;border-radius:50%;display:inline-grid;place-items:center;border:1px solid var(--rule-strong);background:var(--card);font-size:1.15rem;flex:none}
.icon-btn svg{width:22px;height:22px}
.btn-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.btn{flex-direction:column;gap:2px}
.btn .sub{display:block;font-size:.68rem;font-weight:400;opacity:.75;letter-spacing:.01em}
/* progress */
.bar{height:10px;border-radius:99px;background:var(--pen-soft);overflow:hidden}
.stage{border-top:1px dashed var(--rule-strong);padding-top:10px;display:flex;flex-direction:column;gap:6px}
.bar>i{display:block;height:100%;background:var(--pen);border-radius:99px;transition:width .3s ease}
.big-num{font-family:var(--f-word);font-size:2.3rem;line-height:1;font-variant-numeric:tabular-nums}
/* ladder */
.ladder{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:2px}
.rung{border:1px solid var(--rule-strong);border-radius:12px;padding:10px 12px;background:var(--paper);display:flex;flex-direction:column;gap:2px;text-align:left;min-height:76px}
.rung .lvl{font-size:.7rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:700}
.rung .name{font-weight:700}
.rung .st{font-size:.82rem;color:var(--muted);font-variant-numeric:tabular-nums;margin-top:auto}
.rung.passed{background:var(--good-soft);border-color:transparent}
.rung.passed .st{color:var(--good);font-weight:700}
.rung.ready{border-color:var(--pen);box-shadow:inset 0 0 0 1px var(--pen);background:var(--card)}
.rung.locked{opacity:.55}
.batch-list{display:flex;flex-direction:column;gap:0}
.batch-list .bl{width:100%;display:flex;flex-direction:column;gap:8px;padding:12px 2px;border-bottom:1px solid var(--rule);font-variant-numeric:tabular-nums;font-size:.92rem}
.batch-list .bl-t{display:flex;align-items:baseline;justify-content:space-between;gap:10px;min-width:0}
.batch-list .bl-a{display:grid;grid-template-columns:.8fr 1fr 1fr;gap:6px}
.batch-list .bl-a .mini{padding:7px 4px;white-space:nowrap;font-size:.8rem}
.mini{border:1px solid var(--rule-strong);background:var(--card);border-radius:9px;padding:7px 10px;font-size:.82rem;font-weight:700;min-height:36px}
.mini.solid{background:var(--pen);border-color:var(--pen);color:var(--pen-ink)}
.batch-list .bl:last-child{border-bottom:0}
.notice{border-radius:12px;padding:12px 14px;background:var(--warn-soft);color:var(--warn);font-size:.9rem}
.notice.good{background:var(--good-soft);color:var(--good)}
/* chips */
.chip{display:inline-flex;align-items:center;padding:2px 9px;border-radius:999px;font-size:.76rem;font-weight:700;background:var(--pen-soft);color:var(--pen);letter-spacing:.02em}
.chip.m{background:var(--masc-soft);color:var(--masc)}
.chip.f{background:var(--fem-soft);color:var(--fem)}
.chip.plain{background:transparent;border:1px solid var(--rule-strong);color:var(--muted);font-weight:400}
/* word card */
.wordcard{text-align:center;display:flex;flex-direction:column;align-items:center;gap:10px;padding:20px 16px}
.visual.flat{min-height:0}
.visual{position:relative;width:100%;max-width:100%;display:flex;justify-content:center;align-items:center;gap:14px;min-height:112px}
.emoji{font-size:4.6rem;line-height:1.1}
.photo{width:128px;height:112px;max-width:45%;border-radius:12px;object-fit:cover;background:var(--pen-soft)}
.photo-x{position:absolute;right:0;bottom:-4px;font-size:.72rem;border:0;background:transparent;color:var(--faint);text-decoration:underline;padding:2px}
.fr{font-family:var(--f-word);font-size:clamp(2.1rem,9vw,2.9rem);line-height:1.1;overflow-wrap:anywhere;margin:0}
.fr .art{color:var(--faint)}
.fr.m .art{color:var(--masc)} .fr.f .art{color:var(--fem)}
.en{font-size:1.2rem;font-weight:700;line-height:1.35}
.example{border-top:1px solid var(--rule);padding-top:12px;margin-top:2px;width:100%;display:flex;gap:12px;align-items:flex-start;text-align:left}
.example .ex-fr{font-family:var(--f-word);font-size:1.08rem}
mark{background:var(--pen-soft);color:var(--ink);border-radius:4px;padding:0 3px;box-decoration-break:clone;-webkit-box-decoration-break:clone}
.feedback mark{background:rgba(127,127,127,.18);color:inherit}
.form-note{font-size:.82rem;color:var(--muted);margin-top:2px}
.contraction{font-size:.82rem;color:var(--muted);margin-top:2px}
.contraction b{color:var(--ink);font-family:var(--f-word);font-weight:400}
.dictform{margin-top:8px;padding:8px 10px;border-radius:10px;background:var(--paper)}
.form-note b{color:var(--ink);font-family:var(--f-word);font-weight:400}
.whybtn{border:1px solid var(--rule-strong);background:var(--card);color:var(--muted);width:20px;height:20px;border-radius:50%;font-size:.7rem;line-height:1;padding:0;vertical-align:middle}
/* reading */
.article{font-family:var(--f-word);font-size:1.12rem;line-height:1.85}
.article .tok{border:0;background:transparent;padding:0 1px;font:inherit;color:inherit;border-radius:4px}
.article .tok.known{background:var(--good-soft);color:var(--good)}
.article .tok.current{background:var(--pen-soft);color:var(--pen)}
.article .tok.soon{border-bottom:1.5px dotted var(--faint)}
.slots{display:flex;flex-wrap:wrap;gap:6px;min-height:52px;padding:10px;border:1.5px dashed var(--rule-strong);border-radius:12px;align-items:center}
.tiles{display:flex;flex-wrap:wrap;gap:6px}
.tile{font-family:var(--f-word);font-size:1.05rem;padding:8px 12px;border-radius:10px;border:1px solid var(--rule-strong);background:var(--card)}
.tile.placed{background:var(--pen-soft);border-color:var(--pen);color:var(--pen)}
.tile.good{background:var(--good-soft);border-color:var(--good);color:var(--good)}
.tile.bad{background:var(--bad-soft);border-color:var(--bad);color:var(--bad)}
.article-img{width:100%;max-height:200px;object-fit:cover;border-radius:12px}
.legend{display:flex;gap:12px;flex-wrap:wrap;font-size:.78rem;color:var(--muted)}
.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:4px;vertical-align:-1px}
.reveal{border:1px dashed var(--rule-strong);border-radius:10px;padding:10px 16px;background:transparent;color:var(--muted);width:100%}
/* quiz */
.qhead{position:sticky;top:calc(env(safe-area-inset-top,0px) + 54px);z-index:5;display:flex;align-items:center;gap:12px;margin-bottom:12px;
  padding-block:8px;background:color-mix(in srgb,var(--paper) 90%,transparent);backdrop-filter:blur(6px)}
.sticky-bar{position:sticky;bottom:calc(env(safe-area-inset-bottom,0px) + 8px);z-index:4;padding-top:8px;
  background:linear-gradient(to top,var(--paper) 72%,transparent)}
.qhead .bar{flex:1}
.prompt{min-height:180px;justify-content:center}
.options{display:grid;grid-template-columns:1fr;gap:10px}
@media (min-width:480px){.options{grid-template-columns:1fr 1fr}}
.opt{min-height:56px;padding:12px 14px;border-radius:12px;border:1.5px solid var(--rule-strong);background:var(--card);text-align:left;font-weight:700;display:flex;align-items:center;gap:10px}
.opt .k{flex:none;width:24px;height:24px;border-radius:6px;border:1px solid var(--rule-strong);display:grid;place-items:center;font-size:.72rem;color:var(--faint)}
.opt.fr-opt{font-family:var(--f-word);font-weight:400;font-size:1.15rem}
.opt.correct{border-color:var(--good);background:var(--good-soft);color:var(--good)}
.opt.wrong{border-color:var(--bad);background:var(--bad-soft);color:var(--bad)}
.opt[disabled]{cursor:default}
.type-in{width:100%;font-family:var(--f-word);font-size:1.5rem;padding:12px 14px;border-radius:12px;border:1.5px solid var(--rule-strong);background:var(--card);text-align:center}
.type-in:focus{outline:none;border-color:var(--pen)}
.type-in.correct{border-color:var(--good);background:var(--good-soft)}
.type-in.wrong{border-color:var(--bad);background:var(--bad-soft)}
.accents{display:flex;flex-wrap:wrap;gap:6px;justify-content:center}
.accents button{min-width:40px;height:40px;border-radius:8px;border:1px solid var(--rule-strong);background:var(--card);font-family:var(--f-word);font-size:1.05rem}
.feedback{border-radius:12px;padding:12px 14px;display:flex;flex-direction:column;gap:4px;text-align:left}
.feedback.good{background:var(--good-soft);color:var(--good)}
.feedback.bad{background:var(--bad-soft);color:var(--bad)}
.feedback .hand{font-family:var(--f-hand);font-size:1.15rem}
.feedback .fb-body{color:var(--ink)}
.listen-hero{display:flex;gap:14px;justify-content:center;align-items:center}
.play-big{width:96px;height:96px;border-radius:50%;border:0;background:var(--pen);color:var(--pen-ink);display:grid;place-items:center}
.play-big svg{width:40px;height:40px}
.result-score{font-family:var(--f-word);font-size:4rem;line-height:1}
.praise{font-family:var(--f-hand);font-size:1.6rem;color:var(--pen)}
.missed{display:flex;flex-direction:column}
.missed .mrow{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--rule)}
.missed .mrow:last-child{border-bottom:0}
.mrow .w{font-family:var(--f-word);font-size:1.05rem}
/* word list */
.search{width:100%;padding:12px 14px;border-radius:12px;border:1px solid var(--rule-strong);background:var(--card)}
.sticky-search{position:sticky;top:calc(env(safe-area-inset-top,0px) + 54px);z-index:5;display:flex;flex-direction:column;gap:8px;
  padding-block:8px;background:color-mix(in srgb,var(--paper) 92%,transparent);backdrop-filter:blur(6px)}
.filters{display:flex;gap:6px;flex-wrap:wrap}
.filters button{padding:6px 12px;border-radius:999px;border:1px solid var(--rule-strong);background:var(--card);font-size:.86rem}
.filters button[aria-pressed="true"]{background:var(--ink);color:var(--paper);border-color:var(--ink)}
.wl{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--rule-strong);border-radius:var(--radius);overflow:hidden}
.wrow{display:grid;grid-template-columns:44px 1fr auto;gap:10px;align-items:center;padding:10px 12px;border:0;border-bottom:1px solid var(--rule);background:transparent;text-align:left;width:100%}
.wrow:last-child{border-bottom:0}
.wrow .n{font-size:.76rem;color:var(--faint);font-variant-numeric:tabular-nums}
.wrow .t{display:flex;flex-direction:column;min-width:0}
.wrow .t b{font-family:var(--f-word);font-weight:400;font-size:1.08rem}
.wrow .t span{font-size:.86rem;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dot{width:10px;height:10px;border-radius:50%;background:var(--rule-strong)}
.dot.learned{background:var(--good)} .dot.current{background:var(--pen)} .dot.due{background:var(--warn)}
/* settings */
.field{display:flex;flex-direction:column;gap:6px}
.field label{font-weight:700}
.field select,.field input[type=number],.field textarea{padding:10px 12px;border-radius:10px;border:1px solid var(--rule-strong);background:var(--card)}
.field textarea{min-height:84px;font:12px/1.4 ui-monospace,Menlo,monospace;resize:vertical}
details.card>summary{cursor:pointer;list-style:none;font-size:1rem}
details.card>summary::-webkit-details-marker{display:none}
details.card>summary::after{content:"▾";float:right;color:var(--muted)}
details.card[open]>summary::after{content:"▴"}
.switch{display:flex;justify-content:space-between;align-items:center;gap:12px}
.switch input{width:22px;height:22px;accent-color:var(--pen)}
/* tab bar */
.tabs{position:fixed;left:0;right:0;bottom:0;z-index:10;background:var(--card);border-top:1px solid var(--rule-strong);padding-bottom:env(safe-area-inset-bottom,0px)}
.tabs nav{max-width:600px;margin:0 auto;display:grid;grid-template-columns:repeat(4,1fr)}
.tabs button{border:0;background:transparent;padding:10px 4px 12px;display:flex;flex-direction:column;align-items:center;gap:2px;font-size:.76rem;color:var(--muted)}
.tabs button svg{width:22px;height:22px}
.tabs button[aria-current="page"]{color:var(--pen);font-weight:700}
/* modal */
.modal{position:fixed;inset:0;z-index:20;background:rgba(10,14,28,.5);display:flex;align-items:flex-end;justify-content:center;padding:16px}
.modal .sheet{width:100%;max-width:560px;max-height:90%;overflow:auto;margin-bottom:env(safe-area-inset-bottom,0px)}
@media (min-width:640px){.modal{align-items:center}}
.toast{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(84px + env(safe-area-inset-bottom,0px));background:var(--ink);color:var(--paper);padding:10px 16px;border-radius:10px;font-size:.9rem;z-index:30;max-width:calc(100% - 32px)}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
.pop{animation:pop .25s ease}
@keyframes pop{from{transform:scale(.96);opacity:.6}to{transform:none;opacity:1}}

:root{--maple:#EAD3A0;--maple-line:#B38F55;--rose:#5B2E22;--string:#7A8185}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--maple:#B8975F;--maple-line:#7E6238;--string:#C3CBCD}}
:root[data-theme="dark"]{--maple:#B8975F;--maple-line:#7E6238;--string:#C3CBCD}
.fbwrap{overflow-x:auto;width:100%;margin:2px 0}
.fretsvg{width:100%;max-width:560px;display:block;height:auto;margin:0 auto}
.fretsvg .board{fill:var(--maple)}
.fretsvg .fretline{stroke:var(--maple-line);stroke-width:2}
.fretsvg .nut{stroke:var(--rose);stroke-width:6}
.fretsvg .str{stroke:var(--string)}
.fretsvg .inlay{fill:var(--maple-line);opacity:.4}
.fretsvg .fnum{fill:var(--muted);font-size:11px;text-anchor:middle}
.fdot circle{stroke:#fff;stroke-width:2}
.fdot text{fill:#fff;font:700 11px var(--f-ui);text-anchor:middle;pointer-events:none}
.d-note circle{fill:var(--rose)}.d-root circle{fill:var(--pen)}.d-sel circle{fill:var(--ink)}.d-ok circle{fill:var(--good)}.d-bad circle{fill:var(--bad)}
.rowhl{fill:var(--pen);opacity:.16}
.cell{fill:transparent;cursor:pointer}.cell:hover{fill:rgba(255,255,255,.35)}
.cell:focus-visible{outline:3px solid var(--pen)}
.pbtn{border:1px solid var(--rule-strong);background:var(--card);border-radius:10px;padding:8px 14px;font-weight:700;color:var(--ink)}
.pbtn.sm{padding:2px 10px;border-radius:8px}
.tbl{width:100%;border-collapse:collapse;font-size:.92rem;margin:8px 0}
.tbl th,.tbl td{text-align:left;padding:6px 6px;border-bottom:1px solid var(--rule)}
.tbl th{color:var(--muted);font-weight:700;font-size:.74rem;letter-spacing:.06em;text-transform:uppercase}
pre.tab{background:var(--paper);border:1px solid var(--rule-strong);border-radius:10px;padding:12px;overflow-x:auto;font-size:.95rem;line-height:1.3;margin:8px 0}
.wordcard .example{display:block}
.wordcard .example p{margin:0 0 8px}
.fr.ans{max-width:100%}


.ppdemo{width:100%;display:flex;flex-direction:column;align-items:center;margin:8px 0}
.ppd{position:relative;width:100%;max-width:320px;aspect-ratio:16/9;background:#fff;border:1px solid var(--rule-strong);border-radius:8px;overflow:hidden;font-family:var(--f-ui);color:#fff}
.ppd .a,.ppd .b{position:absolute;inset:0;display:grid;place-items:center;font-weight:700}
.ppd .a{background:#2F6BA8}.ppd .b{background:#E0703A}
.ppd i{display:block;position:absolute}
.ppd .t,.ppd .mt{position:absolute;bottom:6px;left:0;right:0;text-align:center;color:#444;font:700 .74rem var(--f-ui)}
.d-fade .b{animation:kfade 4s ease-in-out infinite}
@keyframes kfade{0%,25%{opacity:0}45%,75%{opacity:1}95%,100%{opacity:0}}
.d-push .a{animation:kpa 4s ease-in-out infinite}.d-push .b{animation:kpb 4s ease-in-out infinite}
